import os
from storage_client import get_s3_client
from storage_models import UploadObjectRequest, UploadObjectResponse

def upload_object(request: UploadObjectRequest) -> UploadObjectResponse:
    s3_client = get_s3_client()

    if request.file_path:
        if not os.path.exists(request.file_path):
            raise FileNotFoundError(f"File not found at {request.file_path}")
        extra_args = {}
        s3_client.upload_file(request.file_path, request.bucket_name, request.object_name, ExtraArgs=extra_args)
        response = s3_client.head_object(Bucket=request.bucket_name, Key=request.object_name)
        return UploadObjectResponse(
            object_name=request.object_name,
            e_tag=response['ETag'].strip('\"'),
            version_id=response.get('VersionId')
        )
    elif request.data:
        response = s3_client.put_object(Bucket=request.bucket_name, Key=request.object_name, Body=request.data)
        return UploadObjectResponse(
            object_name=request.object_name,
            e_tag=response['ETag'].strip('\"'),
            version_id=response.get('VersionId')
        )
    else:
        raise ValueError("Either file_path or data must be provided for upload.")

from storage_client import get_s3_client
from storage_models import PresignedDownloadRequest, PresignedDownloadResponse

def create_presigned_download_url(request: PresignedDownloadRequest) -> PresignedDownloadResponse:
    s3_client = get_s3_client()
    try:
        url = s3_client.generate_presigned_url(
            'get_object',
            Params={'Bucket': request.bucket_name,
                    'Key': request.object_name},
            ExpiresIn=request.expires_in
        )
        return PresignedDownloadResponse(url=url)
    except Exception as e:
        raise RuntimeError(f"Error generating presigned URL: {e}")

from storage_client import get_s3_client
from storage_models import ObjectMetadataRequest, ObjectMetadataResponse

def get_object_metadata(request: ObjectMetadataRequest) -> ObjectMetadataResponse:
    s3_client = get_s3_client()
    try:
        response = s3_client.head_object(
            Bucket=request.bucket_name,
            Key=request.object_name
        )

        return ObjectMetadataResponse(
            object_name=request.object_name,
            last_modified=response['LastModified'].isoformat(),
            size=response['ContentLength'],
            content_type=response['ContentType'],
            e_tag=response['ETag'].strip('\"'),
            metadata=response.get('Metadata', {})
        )
    except s3_client.exceptions.ClientError as e:
        if e.response['Error']['Code'] == 'NotFound':
            raise FileNotFoundError(f"Object {request.object_name} not found in bucket {request.bucket_name}")
        else:
            raise RuntimeError(f"Error retrieving object metadata: {e}")

from storage_client import get_s3_client
from storage_models import ListPrefixRequest, ListPrefixResponse, ListPrefixItem

def list_objects_with_prefix(request: ListPrefixRequest) -> ListPrefixResponse:
    s3_client = get_s3_client()
    try:
        params = {
            'Bucket': request.bucket_name,
            'Prefix': request.prefix
        }
        if request.delimiter:
            params['Delimiter'] = request.delimiter
        if request.max_keys:
            params['MaxKeys'] = request.max_keys

        response = s3_client.list_objects_v2(**params)

        contents = response.get('Contents', [])
        items = [
            ListPrefixItem(
                key=obj['Key'],
                last_modified=obj['LastModified'].isoformat(),
                size=obj['Size'],
                e_tag=obj['ETag'].strip('\"')
            )
            for obj in contents
        ]

        common_prefixes = [
            prefix['Prefix'] for prefix in response.get('CommonPrefixes', [])
        ]

        return ListPrefixResponse(
            items=items,
            common_prefixes=common_prefixes
        )
    except Exception as e:
        raise RuntimeError(f"Error listing objects with prefix: {e}")

import os
import boto3
from storage_models import StoredDocumentOcrRequest, StoredDocumentOcrResponse

def get_textract_client():
    aws_access_key_id = os.environ.get("AWS_ACCESS_KEY_ID")
    aws_secret_access_key = os.environ.get("AWS_SECRET_ACCESS_KEY")
    aws_region = os.environ.get("AWS_REGION", "us-east-1")

    if not aws_access_key_id or not aws_secret_access_key:
        raise ValueError("AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY environment variables must be set.")

    textract_client = boto3.client(
        "textract",
        aws_access_key_id=aws_access_key_id,
        aws_secret_access_key=aws_secret_access_key,
        region_name=aws_region
    )
    return textract_client

def run_document_ocr(request: StoredDocumentOcrRequest) -> StoredDocumentOcrResponse:
    textract_client = get_textract_client()

    response = textract_client.detect_document_text(
        Document={
            'S3Object': {
                'Bucket': request.bucket_name,
                'Name': request.object_name
            }
        }
    )

    text_content = []
    for item in response.get('Blocks', []):
        if item['BlockType'] == 'LINE':
            text_content.append(item['Text'])

    # Textract does not directly return detected languages in detect_document_text.
    # For a realistic scenario, one might use AWS Comprehend afterwards for language detection.
    # For this exercise, we will return a placeholder or infer from the context if possible.
    # As the task specifies concrete provider, I'll return an empty list for now.
    detected_languages = [] 

    return StoredDocumentOcrResponse(
        text_content="\n".join(text_content),
        detected_languages=detected_languages
    )
